import java.util.*;

public class Main {
    static final long MOD = 1000000007L;

    static class Mint {
        long v;
        static final Mint ONE = new Mint(1);
        static final Mint ZERO = new Mint(0);

        Mint() { v = 0; }
        Mint(long x) {
            x %= MOD;
            if (x < 0) x += MOD;
            v = x;
        }

        Mint set(long x) {
            x %= MOD;
            if (x < 0) x += MOD;
            v = x;
            return this;
        }

        Mint add(Mint other) {
            long res = v + other.v;
            if (res >= MOD) res -= MOD;
            return new Mint(res);
        }

        Mint sub(Mint other) {
            long res = v - other.v;
            if (res < 0) res += MOD;
            return new Mint(res);
        }

        Mint mul(Mint other) {
            return new Mint((v * other.v) % MOD);
        }

        Mint div(Mint other) {
            return this.mul(other.inv());
        }

        Mint pow(long e) {
            Mint x = this;
            Mint r = new Mint(1);
            while (e > 0) {
                if ((e & 1) == 1) r = r.mul(x);
                x = x.mul(x);
                e >>= 1;
            }
            return r;
        }

        Mint inv() {
            return pow(MOD - 2);
        }

        @Override
        public String toString() {
            return Long.toString(v);
        }
    }

    // Comparator for List<Integer> lexicographic order
    static Comparator<List<Integer>> listComp = (a, b) -> {
        int len = Math.min(a.size(), b.size());
        for (int i = 0; i < len; i++) {
            int cmp = a.get(i).compareTo(b.get(i));
            if (cmp != 0) return cmp;
        }
        return a.size() - b.size();
    };

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Mint[][] mat = new Mint[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int x = sc.nextInt();
                mat[i][j] = new Mint(x).div(new Mint(100));
            }
        }

        TreeMap<List<Integer>, Mint> stsMap = new TreeMap<>(listComp);
        List<Integer> initKey = new ArrayList<>();
        initKey.add(0);
        stsMap.put(initKey, Mint.ONE);

        for (int ph = 0; ph < n; ph++) {
            TreeMap<List<Integer>, Mint> nstsMap = new TreeMap<>(listComp);
            for (int f = 1; f < (1 << n); f++) {
                Mint freq = Mint.ONE;
                for (int i = 0; i < n; i++) {
                    if (((f >> i) & 1) == 1) {
                        freq = freq.mul(mat[ph][i]);
                    } else {
                        freq = freq.mul(Mint.ONE.sub(mat[ph][i]));
                    }
                }
                for (Map.Entry<List<Integer>, Mint> entry : stsMap.entrySet()) {
                    List<Integer> st = entry.getKey();
                    Mint val = entry.getValue();
                    TreeSet<Integer> nstSet = new TreeSet<>();
                    for (int d : st) {
                        for (int i = 0; i < n; i++) {
                            if (((d >> i) & 1) != 0) continue;
                            if (((f >> i) & 1) == 0) continue;
                            nstSet.add(d ^ (1 << i));
                        }
                    }
                    if (nstSet.isEmpty()) continue;
                    List<Integer> nst = new ArrayList<>(nstSet);
                    Mint addVal = val.mul(freq);
                    nstsMap.merge(nst, addVal, (a, b) -> a.add(b));
                }
            }
            stsMap = nstsMap;
        }

        Mint ans = Mint.ZERO;
        if (!stsMap.isEmpty()) {
            ans = stsMap.firstEntry().getValue();
        }
        System.out.println(ans);
    }
}
